bundle D4_unparenthesized_precedence {
  frame {
    system Test;
    namespace Logic;
    scale unit;
    task check;
    regime nominal;
  }

  evaluator ev0 {
    kind model;
    binding test://eval/atoms_v2;
  }

  resolution_policy rp0 {
    kind single;
    members [ev0];
  }

  local {
    c1: t AND f OR t;
    c2: f AND t OR t;
    c3: n OR t AND b;
  }
}

bundle D5_session_shared_state {
  frame {
    system Test;
    namespace Baseline;
    scale service;
    task compare;
    regime nominal;
  }

  evaluator ev0 {
    kind model;
    binding test://eval/baseline_match_v1;
  }

  resolution_policy rp0 {
    kind single;
    members [ev0];
  }

  baseline b_fixed {
    kind point;
    criterion ref test://baseline/by_context_v1;
    frame @{system=Test, namespace=Baseline};
    evaluation_mode fixed;
  }

  baseline b_step {
    kind point;
    criterion ref test://baseline/by_context_v1;
    frame @{system=Test, namespace=Baseline};
    evaluation_mode on_reference;
  }

  local {
    c_fixed: matches_baseline(sensor_A, |0:b_fixed|);
    c_step: matches_baseline(sensor_A, |0:b_step|);
  }
}

bundle D6_claim_subset {
  frame {
    system Test;
    namespace Logic;
    scale unit;
    task check;
    regime nominal;
  }

  evaluator ev0 {
    kind model;
    binding test://eval/atoms_v2;
  }

  resolution_policy rp0 {
    kind single;
    members [ev0];
  }

  local {
    c_keep: t;
    c_drop: f;
  }
}
